import re
s = open('index.html').read()
old = """  function drawDoorPanel(xa, xb, y0, y1, z, isLeft, openAmount) {
    var midX = (SHAFT_X0 + SHAFT_W / 2 - 0.12); // car front center approx
    var halfW = (xb - xa);
    var slide = halfW * openAmount;
    var xA, xB;
    if (isLeft) { xA = xa; xB = midX - slide; }
    else { xA = midX + slide; xB = xb; }"""
new = """  function drawDoorPanel(xa, xb, y0, y1, z, isLeft, openAmount) {
    var halfW = Math.abs(xb - xa);
    var slide = halfW * openAmount;
    var xA, xB;
    if (isLeft) { xA = xa; xB = xb - slide; }
    else { xA = xa + slide; xB = xb; }"""
assert old in s
s = s.replace(old, new)
open('index.html','w').write(s)
print('ok')
EOF

